$ErrorActionPreference = "Stop"
$Root = Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location $Root

Write-Host "N-MEGA2 2014 builder/progression paketi uygulanıyor..." -ForegroundColor Cyan
New-Item -ItemType Directory -Force -Path (Join-Path $Root "scripts") | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $Root "src\certification\player-readiness") | Out-Null

[IO.File]::WriteAllBytes((Join-Path $Root "scripts\n-mega2-2014-builder-progression-audit.mjs"), [Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes((Join-Path $Root "src\certification\player-readiness\nMega2Audit.test.ts"), [Convert]::FromBase64String(""))

$PackagePath = Join-Path $Root "package.json"
$BackupPath = Join-Path $Root "package.n-mega2.backup.json"
if (-not (Test-Path $BackupPath)) { Copy-Item $PackagePath $BackupPath -Force }

$PatchScript = @'
import fs from "node:fs";
const file = "package.json";
const pkg = JSON.parse(fs.readFileSync(file, "utf8"));
pkg.scripts ??= {};
pkg.scripts["audit:player-system:n-mega2"] = "node scripts/n-mega2-2014-builder-progression-audit.mjs";
pkg.scripts["test:n-mega2"] = "vitest run src/certification/player-readiness/nMega2Audit.test.ts src/core/rulesets/levelOneToTwentyJourney.test.ts src/core/rulesets/classProgressionAudit.test.ts src/core/rulesets/characterValidation.test.ts src/core/rulesets/subclassRules.test.ts src/core/rulesets/classSpellSelectionRules.test.ts src/core/rulesets/ancestryChoiceRules.test.ts src/core/rulesets/unifiedCharacterChoices.test.ts src/core/rulesets/level20Certification.test.ts src/core/rulesets/singleClassPlayableReadiness.test.ts";
pkg.scripts["certify:n-mega2"] = "npm run audit:player-system:n-mega2 && npm run test:n-mega2 && npm run build";
fs.writeFileSync(file, JSON.stringify(pkg, null, 2) + "\n");
'@
$PatchTemp = Join-Path $env:TEMP "e4-n-mega2-package-patch.mjs"
Set-Content -Path $PatchTemp -Value $PatchScript -Encoding UTF8
node $PatchTemp
Remove-Item $PatchTemp -Force -ErrorAction SilentlyContinue

if (Test-Path (Join-Path $Root "patch")) { Remove-Item (Join-Path $Root "patch") -Recurse -Force }
if (Test-Path (Join-Path $Root "payload")) { Remove-Item (Join-Path $Root "payload") -Recurse -Force }

Write-Host "N-MEGA2 audit + regression + build çalıştırılıyor..." -ForegroundColor Yellow
npm.cmd run certify:n-mega2
if ($LASTEXITCODE -ne 0) { throw "N-MEGA2 sertifikasyonu başarısız oldu. Terminal çıktısını gönderin." }
Write-Host "N-MEGA2 GREEN" -ForegroundColor Green
Write-Host "Rapor: certification-reports\n-mega2\N_MEGA2_SUMMARY.md"
